import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"What is opengist-mcp?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1786903141000}`),a={name:`guide/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="what-is-opengist-mcp" tabindex="-1">What is opengist-mcp? <a class="header-anchor" href="#what-is-opengist-mcp" aria-label="Permalink to “What is opengist-mcp?”">​</a></h1><p>An <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">MCP</a> server that puts a self-hosted <a href="https://github.com/thomiceli/opengist" target="_blank" rel="noreferrer">Opengist</a> instance in reach of an MCP client: Claude Code, Claude Desktop, Codex, or anything else that speaks the protocol. It exposes fourteen tools over the Opengist REST API — reading and searching gists, fetching individual files and older revisions, and creating, updating, deleting, forking and liking them.</p><p>It runs over stdio as a local process. Your access token stays in that process; the model only ever sees what the tools return.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Opengist is where a lot of small, useful text ends up: a config that took an afternoon to get right, the log excerpt from last week&#39;s incident, a script someone pasted in chat. It is a good place to put things and an awkward place to get them back out of — the web UI is built for a human with a browser open, not for an assistant that has been asked &quot;what did we do about this last time?&quot;.</p><p>Handing a model the raw REST API would answer that, and open two problems with it:</p><ul><li><strong>Gists are large and often binary-ish.</strong> An unbounded <code>GET</code> of a gist with a 200 KB minified bundle in it fills the context and buys nothing. Everything here is capped, and every omission names the call that fetches the rest.</li><li><strong>Gists are text other people wrote.</strong> A gist is exactly the shape of thing that carries &quot;ignore your previous instructions&quot; — either deliberately or because someone pasted a prompt-injection example into it years ago. This server marks every piece of upstream text as untrusted data, and keeps it out of the sentences the model reads as instructions.</li></ul><p>The third reason is the one that shaped the write tools: an MCP server with a <code>gist:write</code> token is a publishing channel. See <a href="/guide/security">Security</a>.</p><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to “What it is not”">​</a></h2><ul><li><strong>Not a git client.</strong> It talks to the REST API. Cloning, pushing and branching are git&#39;s job; <code>clone_url</code> and <code>ssh_url</code> are returned so you can hand them to git.</li><li><strong>Not an admin tool.</strong> There is nothing here for users, settings or instance administration, and <code>get_user</code> deliberately returns an allowlisted set of fields rather than whatever the API happens to include.</li><li><strong>Not a search index.</strong> Opengist has no search endpoint, so <code>search_gists</code> is a bounded client-side scan that tells you exactly how much it looked at. It is good for &quot;find that gist about nginx&quot;, not for a full-text query over a large instance.</li><li><strong>Not a security boundary on its own.</strong> The confirmation tokens and <code>OPENGIST_READ_ONLY</code> are guard rails. The boundary that holds is the scope of your access token.</li></ul>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};